{"id":"m8a1","title":"Tự động gợi ý từ khóa (Trie)","description":"Yêu cầu: Ông tìm kiếm cần gợi ý từ khóa. Xây dựng Trie và viết hàm `countPrefix(words, prefix)` đếm xem có bao nhiêu từ trong danh sách `words` bắt đầu bằng `prefix` cho trước (không phân biệt các từ lặp — mỗi từ đếm 1 lần). Trả về số nguyên.","initialCode":"function countPrefix(words, prefix) {
  const trie = {};
  for (const w of words) {
    let node = trie;
    for (const ch of w) {
      if (!node[ch]) node[ch] = {};
      node = node[ch];
    }
    node.isEnd = true;
  }
  let cur = trie;
  for (const ch of prefix) {
    if (!cur[ch]) return 0;
    cur = cur[ch];
  }
  // đếm số từ trong nhánh bắt đầu từ cur
  function count(node) {
    let c = node.isEnd ? 1 : 0;
    for (const k of Object.keys(node)) {
      if (k !== 'isEnd') c += count(node[k]);
    }
    return c;
  }
  return count(cur);
}","entryFunction":"countPrefix","hints":["Chèn từng từ vào trie, đánh dấu isEnd.","Đi theo prefix; thiếu node thì trả 0.","Đệ quy đếm mọi từ trong nhánh còn lại."],"testCases":[{"input":"[["apple","app","apricot","banana"],"ap"]","expectedOutput":"3"},{"input":"[["cat","car","dog"],"ca"]","expectedOutput":"2"},{"input":"[["abc"],"d"]","expectedOutput":"0"},{"input":"[["prefix","pre","pre"],"pre"]","expectedOutput":"2"}]}
